#include <iostream>
#include <vector>
#include <map>
#include <algorithm>

using namespace std;

void solve() {
    int n;
    cin >> n;
    long long total_sum = 0;
    map<int, int> freq;

    int max_f = 0;
    int maj_val = 0;

    for (int i = 0; i < n; i++) {
        int x;
        cin >> x;
        total_sum += x;
        freq[x]++;
        if (freq[x] > max_f) {
            max_f = freq[x];
            maj_val = x;
        }
    }

    int others = n - max_f;

    int max_majority_played = min(max_f, others + 2);

    long long ans = (total_sum - 1LL * max_f * maj_val) + 1LL * max_majority_played * maj_val;
    cout << ans << "\n";
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int t; cin >> t;
    while(t--) {
        solve();
    }
    return 0;
}

#include <iostream>
#include <string>
#include <cmath>
#include <algorithm>

using namespace std;

void solve() {
    int n; cin >> n;
    string s; cin >> s;

    int n0 = 0, n1 = 0;
    for (char c : s) {
        if (c == '0') n0++;
        else n1++;
    }

    int delta_n = n0 - n1;
    if (abs(delta_n) > 2) {
        cout << -1 << "\n";
        return;
    }

    int L = 1;
    int L0 = (s[0] == '0' ? 1 : 0);
    int L1 = (s[0] == '1' ? 1 : 0);

    for (int i = 1; i < n; i++) {
        if (s[i] != s[i - 1]) {
            L++;
            if (s[i] == '0') L0++;
            else L1++;
        }
    }

    int delta_L = L0 - L1;
    int ans = (n - L) + max(0, abs(delta_n - delta_L) - 1);
    cout << ans << "\n";
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int t; cin >> t;
    while(t--) {
        solve();
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

void solve() {
    int n, m;
    cin >> n >> m;
    vector<long long> v(n + 1);
    for(int i = 1; i <= n; i++) cin >> v[i];

    vector<vector<long long>> a(n + 1, vector<long long>(m));
    for(int i = 1; i <= n; i++) {
        for(int j = 0; j < m; j++) {
            cin >> a[i][j];
        }
    }

    int min_ans = m; 
    vector<long long> best;

    for(int k = n; k >= 1; k--) {
        for(int j = 0; j < m; j++) {
            best.push_back(a[k][j]);
        }

        sort(best.rbegin(), best.rend());

        if ((int)best.size() > m) {
            best.resize(m);
        }

        long long current_sum = 0;
        int pieces = 0;

        for(long long val : best) {
            current_sum += val;
            pieces++;
            if (current_sum >= v[k]) {
                min_ans = min(min_ans, pieces);
                break;
            }
        }
    }

    cout << min_ans << "\n";
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int t; cin >> t;
    while(t--) {
        solve();
    }
    return 0;
}

